-- Read-only Phase 1 verification. Every critical_issues value must be zero.
with required(name) as (values('intermediary_profiles'),('artist_representations'))
select 'missing_tables' check_name,count(*)::bigint critical_issues from required where to_regclass('public.'||name) is null
union all select 'rls_disabled',count(*) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relname in ('intermediary_profiles','artist_representations') and not c.relrowsecurity
union all select 'missing_rpcs',count(*) from (values('public.register_current_user_as_intermediary(text,text)'),('public.save_intermediary_profile(jsonb)'),('public.submit_intermediary_profile()'),('public.request_artist_representation(uuid,jsonb,text)'),('public.respond_to_representation(uuid,boolean)'),('public.submit_artist_artwork(jsonb)'),('public.review_phase1_entity(text,uuid,text,text,bigint)'),('public.review_artist_representation(uuid,boolean,text)'),('public.set_artwork_availability(uuid,text,text)')) f(signature) where to_regprocedure(signature) is null
union all select 'anonymous_rpc_execute',count(*) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in ('register_current_user_as_intermediary','save_intermediary_profile','submit_intermediary_profile','request_artist_representation','respond_to_representation','submit_artist_artwork','review_phase1_entity','review_artist_representation','set_artwork_availability') and has_function_privilege('anon',p.oid,'execute')
union all select 'anonymous_private_table_grants',count(*) from information_schema.role_table_grants where grantee='anon' and table_schema='public' and table_name in ('intermediary_profiles','artist_representations')
union all select 'duplicate_open_representation',count(*) from (select artist_id,intermediary_id from public.artist_representations where status in ('pending_artist','pending_admin','approved') group by artist_id,intermediary_id having count(*)>1) d
union all select 'orphan_representation',count(*) from public.artist_representations r left join public.artist_profiles a on a.id=r.artist_id left join public.intermediary_profiles i on i.id=r.intermediary_id where a.id is null or i.id is null;
